/**
 * Generate the capcontract layer (types + dispatch + binder) from capir/capir.json.
 *
 *   node scripts/gen-capcontract.mjs            # write generated files
 *   node scripts/gen-capcontract.mjs --check    # byte-compare, exit 1 on drift
 *
 * Design constraints (dsh-opentui-024-delivery-plan.md §二 v2.1 + redesign v3 §3.0):
 *  - self-contained: NO @deepseek-ai import; capability ids are string data only.
 *  - every generated file starts with the provenance declaration line.
 *  - generated code declares NO cordis `inject` and touches NO ctx service: the
 *    host invocation surface is injected by bridge via `CapHostInvoke` (R2/R3).
 *  - CapIR v3 carries interface shapes + service/params/result data. JSON Schema
 *    stays in capir.json data layer (bundle-size discipline); only normalised
 *    param rows reach TypeScript. No event-frame sessionId field (still TODO).
 *  - deny-list (AMEND-1): namespace in {account, credentials, settings} gets NO
 *    generic adapter/wire row. These families keep their hand-written arms +
 *    dedicated projections.
 *  - PROJECTED_BY_HAND (AMEND-2): result jsonSchema recursive key scan against
 *    /token|apikey|api_key|secret|password|credential|authorize|bearer/i forces
 *    the id into a hand-projection exception set.
 *  - CAP_GENERIC_ADAPTERS is an explicit per-id release whitelist. W2-0 base:
 *    empty (AMEND-4); wired count unchanged (28), bridge observable behaviour 0 delta.
 *    W2-1 releases the three side-session ids (session/create|prompt|wait).
 *    W2-2 releases seven pluginManager read ids (plan §5.2); writes stay W2-3.
 *    W2-3 releases eight pluginManager write ids (plan §5.2); every one is also
 *    emitted into CAP_WRITE_CONFIRM_IDS so the generic arm refuses it unless an
 *    explicit confirm marker accompanies the call (R6 double gate).
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const ATTRIBUTION =
  "Derived from deepseek-ai/deepseek-harness (MIT, Copyright (c) 2026 DeepSeek)"
const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..")
const CAPIR_PATH = resolve(ROOT, "capir/capir.json")
const OUT_DIR = resolve(ROOT, "capcontract")

const fail = (msg) => {
  console.error("gen-capcontract: " + msg)
  process.exit(1)
}

const capir = JSON.parse(readFileSync(CAPIR_PATH, "utf8"))
if (capir.attribution !== ATTRIBUTION) fail("capir attribution mismatch")
if (capir.schema !== "dsh-opentui.capir/3") fail("unexpected capir schema: " + capir.schema)

const methods = capir.artifacts.flatMap((a) => a.methods)
const ids = methods.map((m) => m.id)
if (ids.length !== capir.totals.methods) fail("capir method count mismatch")
if (new Set(ids).size !== ids.length) fail("duplicate method id in capir")
if (methods.some((m) => m.class !== "W")) fail("non-W method in capir")
if (methods.some((m) => m.kind !== "unary" && m.kind !== "stream")) fail("unexpected method kind")

const q = (s) => JSON.stringify(s)
const header = (what) => [
  `// ${ATTRIBUTION}`,
  `// GENERATED by scripts/gen-capcontract.mjs from capir/capir.json (dsh-opentui.capir/3).`,
  `// ${what} — DO NOT EDIT; regenerate with: node scripts/gen-capcontract.mjs`,
  `// CapIR v3: id/namespace/name/kind/class + service/params/result; no event frame.`,
  `// Params rows are normalised; full JSON Schema stays in capir.json (no bundle bloat).`,
  ``,
].join("\n")

const idsBlock = ids.map((id) => `  ${q(id)},`).join("\n")
const shapesBlock = methods.map((m) =>
  `  { id: ${q(m.id)}, namespace: ${q(m.namespace)}, name: ${q(m.name)}, kind: ${q(m.kind)}, class: ${q(m.class)} },`
).join("\n")
const tableBlock = methods.map((m) => `  ${q(m.id)}: ${q(m.kind)},`).join("\n")

// --- deny-list (AMEND-1 终稿): exact namespace match, three families only ---
const DENY_NAMESPACES = new Set(["account", "credentials", "settings"])
const isDenied = (m) => DENY_NAMESPACES.has(m.namespace)
const genericMethods = methods.filter((m) => !isDenied(m))

// --- service table: id -> cordis service key + target method name ---
// W2-1: carry `cancel: "signal"` through from capir.json so the generic arm can
// append an owned AbortSignal for methods whose host signature requires one
// (session/prompt & session/wait call signal.throwIfAborted() unconditionally).
// Data is additive (only methods with a `cancel` field get the row property).
const serviceBlock = methods.map((m) =>
  `  ${q(m.id)}: { service: ${q(m.service)}, implementation: ${q(m.implementation ?? m.name)}${m.cancel !== undefined ? `, cancel: ${q(m.cancel)}` : ""} },`
).join("\n")

// --- params table: id -> ordered normalised rows (jsonSchema NOT emitted) ---
const paramsBlock = methods.map((m) => {
  const rows = (m.params ?? []).map((p) => {
    let row = `    { name: ${q(p.name)}, required: ${p.required ? "true" : "false"}, type: ${q(p.type)}`
    if (p.enum !== undefined) row += `, enum: [${p.enum.map((v) => q(v)).join(", ")}]`
    return row + " },"
  })
  return `  ${q(m.id)}: [\n${rows.join("\n")}\n  ],`
}).join("\n")

// --- scope table: id -> {context, wire} for CapIR methods carrying a scope block ---
// W2-0 scope-lookup fix. The data is additive (only the 34 scope-bearing methods
// get a row); the generic arm consumes it via injected table to resolve the
// scope wire (e.g. agentId:string) into the live host object the goal-family
// methods require. Fail loud on any malformed scope so a silent wrong shape can
// never reach the generated table. NO goals-specific branch lives in the arm.
const scopeEntries = methods.filter((m) => m.scope !== undefined)
for (const m of scopeEntries) {
  const s = m.scope
  if (s === null || typeof s !== 'object' || Array.isArray(s)
    || typeof s.context !== 'string' || s.context === ''
    || typeof s.wire !== 'string' || s.wire === '') {
    fail("malformed scope block: " + m.id)
  }
  // The scope wire MUST be a declared param of the method (else the resolver
  // would have nothing to substitute) — cross-check against capir params.
  if (!(m.params ?? []).some((p) => p.name === s.wire)) {
    fail("scope wire not present in params: " + m.id + " wire=" + s.wire)
  }
}
const scopeBlock = scopeEntries.map((m) =>
  `  ${q(m.id)}: { context: ${q(m.scope.context)}, wire: ${q(m.scope.wire)} },`
).join("\n")

// --- wire table: <namespace>.<name> -> id (deny-list filtered, bidirectional) ---
const wireEntries = genericMethods.map((m) => ({ wire: `${m.namespace}.${m.name}`, id: m.id }))
const wireSeen = new Set()
for (const e of wireEntries) {
  if (wireSeen.has(e.wire)) fail("duplicate generic wire name: " + e.wire)
  wireSeen.add(e.wire)
}
const wireBlock = wireEntries.map((e) => `  ${q(e.wire)}: ${q(e.id)},`).join("\n")
const wireRevBlock = wireEntries.map((e) => `  ${q(e.id)}: ${q(e.wire)},`).join("\n")

// --- PROJECTED_BY_HAND (AMEND-2): recursive sensitive-key scan of result jsonSchema ---
const SENSITIVE_RE = /token|apikey|api_key|secret|password|credential|authorize|bearer/i
function collectKeys(node, acc) {
  if (node === null || typeof node !== "object") return
  if (Array.isArray(node)) {
    for (const v of node) collectKeys(v, acc)
    return
  }
  for (const [k, v] of Object.entries(node)) {
    acc.add(k)
    collectKeys(v, acc)
  }
}
const projected = methods.filter((m) => {
  const acc = new Set()
  collectKeys(m.result?.jsonSchema, acc)
  return [...acc].some((k) => SENSITIVE_RE.test(k))
})
const projectedBlock = projected.map((m) => `  ${q(m.id)},`).join("\n")
// W2-1 /btw activation: first generic release — the three side-session ids
// (session/create -> prompt -> wait). Explicit per-id whitelist; every other id
// stays hand-wired or NOT_WIRED. Release is per-id per batch (plan §3.1).
const W2_1_ADAPTERS = [
  "@deepseek-ai/dsh-api-session-controller#session/create",
  "@deepseek-ai/dsh-api-session-controller#session/prompt",
  "@deepseek-ai/dsh-api-session-controller#session/wait",
]
// W2-2 /plugins read face: seven pluginManager READ ids (plan §5.2). All unary,
// all service=pluginManager, NO write/install id (those stay W2-3). Release is
// batch-segmented (W2-1 review carry-in #1) so the round log stays auditable.
const W2_2_READ_ADAPTERS = [
  "@deepseek-ai/dsh-plugin-manager#pluginManager/listBundles",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/listPlugins",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/listVersionExemptions",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/registries",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/inspect",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/listVersions",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/readBundleDetail",
]
// W2-3 /plugins write face: eight pluginManager WRITE ids (plan §5.2, R6). All
// unary, all service=pluginManager, NO stream / deny-family id (fail-loud below).
// Each is a FS/config-mutating call that MUST pass the TUI confirm modal; the
// generated CAP_WRITE_CONFIRM_IDS set drives the generic-arm confirm gate.
const W2_3_WRITE_ADAPTERS = [
  "@deepseek-ai/dsh-plugin-manager#pluginManager/installBundle",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/updateBundle",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/removeBundle",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/setBundleEnabled",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/setPluginEnabled",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/setVersionExemption",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/cancelInstall",
  "@deepseek-ai/dsh-plugin-manager#pluginManager/waitForInstall",
]
// W2-4 /directory truth face: five READ directory ids (plan §4.2). All unary,
// no stream / deny-family id (fail-loud below). service=llm(3)/web(1)/
// permissionPresets(1). NOTE: llm/discoverModels IS in CAP_PROJECTED_BY_HAND
// (maxTokens→/token/) — its generic wire reply is refused with
// HAND_PROJECTION_REQUIRED (AMEND-2); the face must hand-project. The handoff
// id claim (listProviders/web in PROJECTED) is a documented erratum — see
// .proof/025-w2-4/00-preregistered-expected.md §1 E5.
const W2_4_DIRECTORY_ADAPTERS = [
  "@deepseek-ai/dsh-llm#llm/listProviders",
  "@deepseek-ai/dsh-llm#llm/listConfigurableProviders",
  "@deepseek-ai/dsh-llm#llm/discoverModels",
  "@deepseek-ai/dsh-web#web/listProviders",
  "@deepseek-ai/dsh-permission-presets#permissionPresets/catalog",
]
// W2-5 /goals face: seven goals ids (plan §4.2). All unary, all service=goals,
// scope {context:agent, wire:agentId} — the wire carries the agentId STRING and
// the arm resolves it in place via CAP_SCOPE_TABLE (data-driven scope
// substitution, d94161a, table-driven — AMEND-5 erratum; not caller-side live).
// NO stream / deny-family id
// (fail-loud below). goals/create has implementation alias remoteExportCreate.
// AMEND-2 blind spot: goals/get result jsonSchema=null and every other goal
// result has additionalProperties:true — NONE is in CAP_PROJECTED_BY_HAND by the
// static scan, so the load-bearing defence is the hand-written seam whitelist
// projection (declared per-id in .proof/025-w2-5/00-preregistered-expected.md §1 E5.b).
const W2_5_GOALS_ADAPTERS = [
  "@deepseek-ai/dsh-goal#goals/create",
  "@deepseek-ai/dsh-goal#goals/get",
  "@deepseek-ai/dsh-goal#goals/edit",
  "@deepseek-ai/dsh-goal#goals/complete",
  "@deepseek-ai/dsh-goal#goals/pause",
  "@deepseek-ai/dsh-goal#goals/resume",
  "@deepseek-ai/dsh-goal#goals/clear",
]
// 026 — commands/execute: the host's registered `/permission <preset>` command
// runner (PV-A). One id, unary, service=commands/impl=execute/cancel=signal,
// scope {context:agent, wire:agentId} — the wire carries the session id STRING
// and the arm resolves it to the live agent (same as goals). result jsonSchema
// is null (W2-4 blind-spot family): default projection assumption declared in
// .proof/026-web-mirror/00-preregistered-expected.md §1 E5; the seam applies
// a hand-written second whitelist. NOT a write-confirm id: the full-access
// confirmation is a TUI modal (W2-3 confirm MODAL paradigm), not the bridge
// __confirm double-gate.
const W2_6_COMMANDS_ADAPTERS = [
  "@deepseek-ai/dsh-commands#commands/execute",
]
// Union of every released id across batches (W2-1 3 + W2-2 7 + W2-3 8 + W2-4 5 + W2-5 7 = 30).
// 026 round log — OLD W2-5 union kept VERBATIM (do not delete):
//   // Union of every released id across batches (W2-1 3 + W2-2 7 + W2-3 8 + W2-4 5 + W2-5 7 = 30).
//   const RELEASED_ADAPTERS = [...W2_1_ADAPTERS, ...W2_2_READ_ADAPTERS, ...W2_3_WRITE_ADAPTERS, ...W2_4_DIRECTORY_ADAPTERS, ...W2_5_GOALS_ADAPTERS]
// 026 releases 1 commands id -> 31.
const RELEASED_ADAPTERS = [...W2_1_ADAPTERS, ...W2_2_READ_ADAPTERS, ...W2_3_WRITE_ADAPTERS, ...W2_4_DIRECTORY_ADAPTERS, ...W2_5_GOALS_ADAPTERS, ...W2_6_COMMANDS_ADAPTERS]
for (const id of RELEASED_ADAPTERS) {
  if (!ids.includes(id)) fail("released adapter id not in CapIR: " + id)
}
if (new Set(RELEASED_ADAPTERS).size !== RELEASED_ADAPTERS.length) fail("duplicate released adapter id")
const adapterBlock = RELEASED_ADAPTERS.map((id) => `  ${q(id)},`).join("\n")
// Fail-loud: no released id may be a stream kind or a deny-list family (R6 / AMEND-1/§3.6).
for (const id of RELEASED_ADAPTERS) {
  const m = methods.find((x) => x.id === id)
  if (!m) fail("released adapter has no method: " + id)
  if (m.kind === "stream") fail("released adapter is stream (unary arm only): " + id)
  if (isDenied(m)) fail("released adapter is deny-list family: " + id)
}
// CAP_WRITE_CONFIRM_IDS: every W2-3 write id requires an explicit confirm marker.
const confirmBlock = W2_3_WRITE_ADAPTERS.map((id) => `  ${q(id)},`).join("\n")

const types = header("types: generated capability id/shape surface") + `
/** Transport kind of a capability method (CapIR field: kind). */
export type CapMethodKind = "unary" | "stream"

/** Static capability class (CapIR field: class; W = wire/client-callable). */
export type CapMethodClass = "W"

/** One normalised row of a generated CapIR params table (data only, no host import). */
export interface CapParamRow {
  readonly name: string
  readonly required: boolean
  readonly type: "string" | "boolean" | "number" | "object" | "array" | "union"
  readonly enum?: readonly (string | boolean | number)[]
}

/**
 * One CapIR method shape, mapping 1:1 to capir.json artifacts[].methods[].
 * TODO(CapIR): event-frame sessionId field (redesign v3 §3.1) — absent in CapIR.
 */
export interface CapMethodShape {
  readonly id: string
  readonly namespace: string
  readonly name: string
  readonly kind: CapMethodKind
  readonly class: CapMethodClass
  // TODO(CapIR): sessionId?: string
}

/** All CapIR method ids as generated string literals (data, not host symbols). */
export const CAP_METHOD_IDS = [
${idsBlock}
] as const

/** Literal union of every generated CapIR method id. */
export type CapMethodId = (typeof CAP_METHOD_IDS)[number]

/** id -> shape, from the same CapIR rows. */
export const CAP_METHODS: readonly CapMethodShape[] = [
${shapesBlock}
] as const

/** Counts mirrored from capir.json totals; cross-checked by the CI integrity gate. */
export const CAP_TOTALS = {
  artifacts: ${capir.totals.artifacts},
  methods: ${capir.totals.methods},
  unary: ${capir.totals.methods_by_kind.unary},
  stream: ${capir.totals.methods_by_kind.stream},
  endpoints_session_controller: ${capir.totals.endpoints_session_controller},
} as const

/** Generated id -> cordis service key + target method name (implementation alias or name). */
export const CAP_SERVICE_TABLE = {
${serviceBlock}
} as const

/** id -> ordered coarse params rows. FULL JSON Schema stays in capir.json, not here. */
export const CAP_PARAMS_TABLE = {
${paramsBlock}
} as const

/** Scope lookup metadata (CapIR "scope" block) for the generic arm's data-driven
 *  scope resolver. Only scope-bearing methods get a row; "context" names the
 *  lookup provider (e.g. "agent") and "wire" names the param carrying the wire id.
 *  The arm NEVER hard-codes any namespace/id — it consumes this table verbatim. */
export interface CapScopeMeta {
  readonly context: string
  readonly wire: string
}

/** id -> {context, wire}; absent for methods without a CapIR scope block. */
export const CAP_SCOPE_TABLE: Readonly<Partial<Record<CapMethodId, CapScopeMeta>>> = {
${scopeBlock}
} as const

/** Map a normalised param type to a structural TS type (no host import, no any). */
export type CapParamType<T extends CapParamRow["type"]> =
  T extends "string" ? string :
  T extends "boolean" ? boolean :
  T extends "number" ? number :
  T extends "array" ? readonly unknown[] :
  T extends "union" ? unknown :
  Record<string, unknown>

/** String-literal-data mapping type for a method's params, derived from CAP_PARAMS_TABLE. */
export type CapParamsOf<K extends CapMethodId> = {
  [P in (typeof CAP_PARAMS_TABLE)[K][number] as P["name"]]: P["required"] extends true
    ? CapParamType<P["type"]>
    : CapParamType<P["type"]> | undefined
}

/** wire name (<namespace>.<name>) -> CapMethodId; deny-list families excluded. */
export const CAP_GENERIC_WIRE_METHODS = {
${wireBlock}
} as const

/** Reverse of CAP_GENERIC_WIRE_METHODS: CapMethodId -> wire name. */
export const CAP_GENERIC_WIRE_BY_ID = {
${wireRevBlock}
} as const

/** Explicit per-id generic-adapter release whitelist (W2-0 empty -> W2-1 3 -> W2-2 10 -> W2-3 18). */
export const CAP_GENERIC_ADAPTERS: ReadonlySet<CapMethodId> = new Set([
${adapterBlock}
] as const)

/** W2-3 write ids (R6): generic-arm refuses these unless a confirm marker is present. */
export const CAP_WRITE_CONFIRM_IDS: ReadonlySet<CapMethodId> = new Set([
${confirmBlock}
] as const)

/** ids whose result jsonSchema carries sensitive keys; forced hand projection (AMEND-2). */
export const CAP_PROJECTED_BY_HAND: ReadonlySet<CapMethodId> = new Set([
${projectedBlock}
] as const)

export function isCapMethodId(value: string): boolean {
  return (CAP_METHOD_IDS as readonly string[]).includes(value)
}
`

const dispatch = header("dispatch: generic W-capability dispatcher (host-adapter injected)") + `
import type { CapMethodId } from "./types.js"

/**
 * Handshake comparison key (delivery plan §二 L37 / v2.1 A): a CapIR method id
 * is already <pkg>#<ns>/<method>, identical in shape to typert descriptor.id.
 * The mapping is therefore the identity function; both sides share this rule.
 */
export function toTypertDescriptorId(id: CapMethodId): string {
  return id
}

/** Generated dispatch table: CapIR id -> transport kind (${methods.length} rows). */
export const CAP_DISPATCH_TABLE: Readonly<Record<string, "unary" | "stream">> = {
${tableBlock}
}

/**
 * Look up the transport kind for a CapIR method id. Unknown ids throw loudly;
 * this is the single generated-side contract check (oldfox R1). The error text
 * is retained verbatim for the CI gate assertion.
 */
export function lookupCapKind(methodId: string): "unary" | "stream" {
  const kind = CAP_DISPATCH_TABLE[methodId]
  if (kind === "unary" || kind === "stream") return kind
  throw new Error("capcontract: unknown method id " + methodId)
}

/**
 * Host invocation is injected by the bridge (R2). The generated layer owns only
 * id/kind data and membership checks; it makes NO assumption about any host API
 * surface (no typert.local.invoke/stream, no descriptor.invoke — R5 TODO).
 */
export type CapHostInvoke = (
  methodId: CapMethodId,
  kind: "unary" | "stream",
  params: unknown,
) => Promise<unknown>

/** Generic W dispatcher: id + opaque params -> kind lookup -> injected hostInvoke. */
export function createCapDispatcher(hostInvoke: CapHostInvoke) {
  return async function dispatch(methodId: CapMethodId, params: unknown): Promise<unknown> {
    const kind = lookupCapKind(methodId)
    return hostInvoke(methodId, kind, params)
  }
}
`

const binder = header("binder: stdio wire frame -> dispatch projection binder (host-adapter injected)") + `
import type { CapMethodId } from "./types.js"
import { CAP_METHOD_IDS, isCapMethodId } from "./types.js"
import { createCapDispatcher, type CapHostInvoke } from "./dispatch.js"

/** A stdio wire frame. Params stay typed by CapIR's generated params table. */
export interface CapWireFrame {
  readonly methodId: CapMethodId
  readonly params: unknown
  // TODO(CapIR): sessionId required by redesign v3 §3.1, absent in CapIR.
  // Not asserted here; do not invent a value.
  readonly sessionId?: string
}

export type WireFrameHandler = (frame: CapWireFrame) => Promise<unknown>

/**
 * Bind the wire-frame surface to the injected host dispatcher. Membership is
 * checked against the generated CapIR id set so a stale/unknown id fails loudly.
 * No cordis inject / ctx access here — the bridge assembles hostInvoke (R3).
 */
export function createProjectionBinder(hostInvoke: CapHostInvoke): WireFrameHandler {
  const dispatch = createCapDispatcher(hostInvoke)
  return async function handle(frame) {
    if (!isCapMethodId(frame.methodId)) {
      throw new Error("capcontract: method id not in CapIR set: " + frame.methodId)
    }
    return dispatch(frame.methodId, frame.params)
  }
}

/** Exported for the CI consistency gate; derived from the generated id set. */
export const BINDER_METHOD_COUNT = CAP_METHOD_IDS.length
`

const files = {
  "types.ts": types,
  "dispatch.ts": dispatch,
  "binder.ts": binder,
}

const checkMode = process.argv[2] === "--check"
if (checkMode) {
  let bad = false
  for (const [name, text] of Object.entries(files)) {
    const path = resolve(OUT_DIR, name)
    let actual
    try {
      actual = readFileSync(path, "utf8")
    } catch {
      console.error("gen-capcontract --check: missing file " + path)
      bad = true
      continue
    }
    if (actual !== text) {
      console.error("gen-capcontract --check: DRIFT in " + path)
      bad = true
    }
  }
  if (bad) {
    console.error("capcontract generated files were not produced by the current generator/capir; re-run gen-capcontract.mjs.")
    process.exit(1)
  }
  console.log(`gen-capcontract --check: byte-identical (${Object.keys(files).length} files, ${methods.length} methods)`)
} else {
  mkdirSync(OUT_DIR, { recursive: true })
  for (const [name, text] of Object.entries(files)) {
    writeFileSync(resolve(OUT_DIR, name), text, "utf8")
  }
  console.log(`gen-capcontract: wrote ${Object.keys(files).join(", ")} -> ${OUT_DIR} (${methods.length} methods; deny=${methods.length - genericMethods.length} projected=${projected.length} adapters=${RELEASED_ADAPTERS.length})`)
}
